values (
  'en-jurassic-park-trivia-2',
  'Jurassic Park Trivia: Dinosaurs and the Park',
  'Eight questions on Jurassic Park: the dinosaurs, the park''s science and the characters of the original films.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Where do the scientists get the dinosaur DNA from?","options":[{"id":"a","text":"Fossilized bones","is_correct":false},{"id":"b","text":"Mosquitoes preserved in amber","is_correct":true},{"id":"c","text":"Frozen tissue samples","is_correct":false},{"id":"d","text":"Living reptiles","is_correct":false}],"explanation":"The DNA comes from blood inside mosquitoes trapped in amber."},{"id":"q2","question":"What is Alan Grant''s profession?","options":[{"id":"a","text":"Mathematician","is_correct":false},{"id":"b","text":"Lawyer","is_correct":false},{"id":"c","text":"Paleontologist","is_correct":true},{"id":"d","text":"Game warden","is_correct":false}],"explanation":"Grant is a paleontologist invited to endorse the park."},{"id":"q3","question":"How does Dennis Nedry plan to smuggle dinosaur embryos out of the park?","options":[{"id":"a","text":"In his backpack","is_correct":false},{"id":"b","text":"In a thermos of coffee","is_correct":false},{"id":"c","text":"Sewn into his jacket","is_correct":false},{"id":"d","text":"Inside a shaving-cream can","is_correct":true}],"explanation":"The embryos are hidden in a fake can of Barbasol shaving cream."},{"id":"q4","question":"Who says the famous line ''life finds a way''?","options":[{"id":"a","text":"Ian Malcolm","is_correct":true},{"id":"b","text":"John Hammond","is_correct":false},{"id":"c","text":"Alan Grant","is_correct":false},{"id":"d","text":"Ellie Sattler","is_correct":false}],"explanation":"Chaos theorist Ian Malcolm warns that life cannot be contained."},{"id":"q5","question":"Why can the dinosaurs breed even though all were engineered to be female?","options":[{"id":"a","text":"The lab cloned males too","is_correct":false},{"id":"b","text":"Frog DNA lets some change sex","is_correct":true},{"id":"c","text":"The raptors laid eggs alone","is_correct":false},{"id":"d","text":"The park made a counting error","is_correct":false}],"explanation":"West African frog DNA filled the genetic gaps, letting some dinosaurs change sex."},{"id":"q6","question":"According to Dr. Grant, how does the T. rex detect its prey?","options":[{"id":"a","text":"By smell","is_correct":false},{"id":"b","text":"By sound","is_correct":false},{"id":"c","text":"By movement","is_correct":true},{"id":"d","text":"By body heat","is_correct":false}],"explanation":"Grant explains that its vision is based on movement, so stay still."},{"id":"q7","question":"Which dinosaur spits venom at Dennis Nedry before killing him?","options":[{"id":"a","text":"Velociraptor","is_correct":false},{"id":"b","text":"Compsognathus","is_correct":false},{"id":"c","text":"Pteranodon","is_correct":false},{"id":"d","text":"Dilophosaurus","is_correct":true}],"explanation":"The frilled Dilophosaurus blinds Nedry with its venom."},{"id":"q8","question":"At the climax in the visitor center, what saves the survivors from the raptors?","options":[{"id":"a","text":"The T. rex attacks the raptors","is_correct":true},{"id":"b","text":"The raptors run away","is_correct":false},{"id":"c","text":"The power comes back on","is_correct":false},{"id":"d","text":"A helicopter lands","is_correct":false}],"explanation":"The T. rex bursts in and kills the raptors cornering the group."}]'::jsonb,
  null,
  array['jurassic park', 'trivia', 'dinosaurs', 'movies']::text[],
  3,
  'published',
  false,
  false,
  now()
)
