  'Pirates of the Caribbean Trivia: Jack Sparrow',
  'Eight questions on Pirates of the Caribbean: Jack Sparrow, the Black Pearl, curses and the crew''s legends.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"What is the name of Captain Jack Sparrow''s ship?","options":[{"id":"a","text":"The Flying Dutchman","is_correct":false},{"id":"b","text":"The Black Pearl","is_correct":true},{"id":"c","text":"The Interceptor","is_correct":false},{"id":"d","text":"The Empress","is_correct":false}],"explanation":"Jack''s beloved ship is the Black Pearl, the fastest ship on the seas."},{"id":"q2","question":"What curses the crew of the Black Pearl in the first film?","options":[{"id":"a","text":"A witch''s spell","is_correct":false},{"id":"b","text":"The Aztec gold they stole","is_correct":true},{"id":"c","text":"A pact with Davy Jones","is_correct":false},{"id":"d","text":"A sirens'' song","is_correct":false}],"explanation":"The cursed Aztec gold leaves them immortal, unable to feel anything."},{"id":"q3","question":"What reveals the cursed pirates'' true form?","options":[{"id":"a","text":"Moonlight","is_correct":true},{"id":"b","text":"Sunlight","is_correct":false},{"id":"c","text":"Rain","is_correct":false},{"id":"d","text":"Fire","is_correct":false}],"explanation":"Under moonlight the cursed crew appear as living skeletons."},{"id":"q4","question":"Whose blood is needed to lift the curse?","options":[{"id":"a","text":"Jack Sparrow''s","is_correct":false},{"id":"b","text":"Elizabeth Swann''s","is_correct":false},{"id":"c","text":"Will Turner''s","is_correct":true},{"id":"d","text":"Barbossa''s","is_correct":false}],"explanation":"They need the blood of Bootstrap Bill''s child, Will Turner."},{"id":"q5","question":"What does Jack''s compass point to?","options":[{"id":"a","text":"North","is_correct":false},{"id":"b","text":"The nearest treasure","is_correct":false},{"id":"c","text":"The nearest port","is_correct":false},{"id":"d","text":"Whatever the holder wants most","is_correct":true}],"explanation":"The compass points to the thing its holder desires most."},{"id":"q6","question":"What is the name of Davy Jones'' ship?","options":[{"id":"a","text":"The Flying Dutchman","is_correct":true},{"id":"b","text":"The Black Pearl","is_correct":false},{"id":"c","text":"Queen Anne''s Revenge","is_correct":false},{"id":"d","text":"The Silent Mary","is_correct":false}],"explanation":"Davy Jones commands the Flying Dutchman, ferrying souls lost at sea."},{"id":"q7","question":"Where is Davy Jones'' heart kept?","options":[{"id":"a","text":"Around his neck","is_correct":false},{"id":"b","text":"In the Dead Man''s Chest","is_correct":true},{"id":"c","text":"In the Kraken''s lair","is_correct":false},{"id":"d","text":"Buried in Tortuga","is_correct":false}],"explanation":"His heart is locked in the Dead Man''s Chest; stabbing it makes you captain of the Dutchman."},{"id":"q8","question":"Who is elected Pirate King by the Brethren Court in At World''s End?","options":[{"id":"a","text":"Jack Sparrow","is_correct":false},{"id":"b","text":"Barbossa","is_correct":false},{"id":"c","text":"Will Turner","is_correct":false},{"id":"d","text":"Elizabeth Swann","is_correct":true}],"explanation":"Every captain votes for themselves except Jack, who votes for Elizabeth."}]'::jsonb,
