  '[{"id":"q1","question":"¿Qué pastilla toma Neo para conocer la verdad sobre Matrix?","options":[{"id":"a","text":"La pastilla azul","is_correct":false},{"id":"b","text":"La pastilla roja","is_correct":true},{"id":"c","text":"Una pastilla verde","is_correct":false},{"id":"d","text":"Las dos pastillas","is_correct":false}],"explanation":"La pastilla roja despierta a Neo en el mundo real; la azul lo habría dejado olvidar."},{"id":"q2","question":"¿Cuál es el nombre real de Neo dentro de Matrix?","options":[{"id":"a","text":"Thomas Edison","is_correct":false},{"id":"b","text":"John Smith","is_correct":false},{"id":"c","text":"Thomas Anderson","is_correct":true},{"id":"d","text":"Robert Taylor","is_correct":false}],"explanation":"Su nombre civil es Thomas A. Anderson; Neo es su alias de hacker."},{"id":"q3","question":"¿Cómo se llama la nave de Morfeo?","options":[{"id":"a","text":"Osiris","is_correct":false},{"id":"b","text":"Nebuchadnezzar","is_correct":true},{"id":"c","text":"Logos","is_correct":false},{"id":"d","text":"Mjolnir","is_correct":false}],"explanation":"La Nebuchadnezzar es la nave de Morfeo; Logos y Mjolnir pertenecen a otras tripulaciones."},{"id":"q4","question":"¿Qué agente se convierte en el némesis de Neo?","options":[{"id":"a","text":"El agente Brown","is_correct":false},{"id":"b","text":"El agente Johnson","is_correct":false},{"id":"c","text":"El Arquitecto","is_correct":false},{"id":"d","text":"El agente Smith","is_correct":true}],"explanation":"Smith se libera del sistema y se convierte en un virus que se autorreplica."},{"id":"q5","question":"¿Qué dice Trinity antes de disparar a un agente a quemarropa?","options":[{"id":"a","text":"«Esquiva esto»","is_correct":true},{"id":"b","text":"«Corre, Neo, corre»","is_correct":false},{"id":"c","text":"«No hay cuchara»","is_correct":false},{"id":"d","text":"«Sé kung fu»","is_correct":false}],"explanation":"Trinity dice la frase justo antes de apretar el gatillo en la azotea."},{"id":"q6","question":"¿Cómo entran y salen los rebeldes de Matrix?","options":[{"id":"a","text":"A través de espejos","is_correct":false},{"id":"b","text":"Por puertas ocultas","is_correct":false},{"id":"c","text":"A través de líneas telefónicas fijas","is_correct":true},{"id":"d","text":"A través de sueños","is_correct":false}],"explanation":"Los operadores los conectan por líneas de teléfono; un teléfono que suena es una salida."},{"id":"q7","question":"¿Qué le enseña a Neo el niño que dobla cucharas en casa del Oráculo?","options":[{"id":"a","text":"Que debe esquivar balas","is_correct":false},{"id":"b","text":"Que no hay cuchara","is_correct":true},{"id":"c","text":"Que debe seguir al conejo blanco","is_correct":false},{"id":"d","text":"Que Matrix lo tiene atrapado","is_correct":false}],"explanation":"«No intentes doblar la cuchara; solo intenta darte cuenta de la verdad: no hay cuchara»."},{"id":"q8","question":"En Matrix Revolutions, ¿qué ofrece Neo a las máquinas a cambio de la paz?","options":[{"id":"a","text":"Derrotar al agente Smith","is_correct":true},{"id":"b","text":"Liberar a todos los humanos","is_correct":false},{"id":"c","text":"Volver a Matrix para siempre","is_correct":false},{"id":"d","text":"Destruir él mismo Zion","is_correct":false}],"explanation":"Neo pelea contra Smith en nombre de las máquinas para salvar ambos mundos."}]'::jsonb,
