values (
  'en-back-to-the-future-trivia',
  'Back to the Future Trivia: Marty, Doc and 88 mph',
  'Eight questions on Back to the Future: Marty McFly, Doc Brown, the DeLorean, 1955, 2015 and 88 mph.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"What speed must the DeLorean reach to travel through time?","options":[{"id":"a","text":"55 mph","is_correct":false},{"id":"b","text":"88 mph","is_correct":true},{"id":"c","text":"100 mph","is_correct":false},{"id":"d","text":"121 mph","is_correct":false}],"explanation":"Reaching 88 miles per hour triggers the flux capacitor."},{"id":"q2","question":"According to Doc, how much power does the flux capacitor need?","options":[{"id":"a","text":"1.21 megawatts","is_correct":false},{"id":"b","text":"12.1 gigawatts","is_correct":false},{"id":"c","text":"1.21 gigawatts","is_correct":true},{"id":"d","text":"121 watts","is_correct":false}],"explanation":"''One point twenty-one gigawatts!'' is one of Doc''s most famous lines."},{"id":"q3","question":"What kind of car is the time machine built into?","options":[{"id":"a","text":"A DeLorean","is_correct":true},{"id":"b","text":"A Corvette","is_correct":false},{"id":"c","text":"A Mustang","is_correct":false},{"id":"d","text":"A Ferrari","is_correct":false}],"explanation":"Doc chose the DeLorean DMC-12, with its stainless-steel body and gull-wing doors."},{"id":"q4","question":"To which year does Marty travel in the first film?","options":[{"id":"a","text":"1985","is_correct":false},{"id":"b","text":"2015","is_correct":false},{"id":"c","text":"1885","is_correct":false},{"id":"d","text":"1955","is_correct":true}],"explanation":"Marty lands in 1955 and meets his teenage parents."},{"id":"q5","question":"What is the name of Doc Brown''s dog in 1985?","options":[{"id":"a","text":"Einstein","is_correct":true},{"id":"b","text":"Mozart","is_correct":false},{"id":"c","text":"Tesla","is_correct":false},{"id":"d","text":"Galileo","is_correct":false}],"explanation":"Einstein is the world''s first time traveller; in 1955 Doc''s dog is Copernicus."},{"id":"q6","question":"Which Chuck Berry song does Marty play at the Enchantment Under the Sea dance?","options":[{"id":"a","text":"Roll Over Beethoven","is_correct":false},{"id":"b","text":"Johnny B. Goode","is_correct":true},{"id":"c","text":"Sweet Little Sixteen","is_correct":false},{"id":"d","text":"Maybellene","is_correct":false}],"explanation":"Marty plays ''Johnny B. Goode'', and Marvin Berry phones his cousin Chuck."},{"id":"q7","question":"What fuel does the DeLorean''s time machine originally run on?","options":[{"id":"a","text":"Uranium","is_correct":false},{"id":"b","text":"Solar power","is_correct":false},{"id":"c","text":"Plutonium","is_correct":true},{"id":"d","text":"Mr. Fusion","is_correct":false}],"explanation":"Plutonium stolen from Libyan terrorists powers it; Mr. Fusion only appears at the end."},{"id":"q8","question":"To which year do Doc and Marty travel in Back to the Future Part II?","options":[{"id":"a","text":"2025","is_correct":false},{"id":"b","text":"1999","is_correct":false},{"id":"c","text":"1885","is_correct":false},{"id":"d","text":"2015","is_correct":true}],"explanation":"They travel to October 21, 2015, a future of hoverboards and flying cars."}]'::jsonb,
  null,
