  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿A qué velocidad debe llegar el DeLorean para viajar en el tiempo?","options":[{"id":"a","text":"55 mph","is_correct":false},{"id":"b","text":"88 mph","is_correct":true},{"id":"c","text":"100 mph","is_correct":false},{"id":"d","text":"121 mph","is_correct":false}],"explanation":"Al alcanzar las 88 millas por hora se activa el condensador de flujo."},{"id":"q2","question":"Según Doc, ¿cuánta potencia necesita el condensador de flujo?","options":[{"id":"a","text":"1,21 megavatios","is_correct":false},{"id":"b","text":"12,1 gigavatios","is_correct":false},{"id":"c","text":"1,21 gigavatios","is_correct":true},{"id":"d","text":"121 vatios","is_correct":false}],"explanation":"«¡Un punto veintiún gigavatios!» es una de las frases más famosas de Doc."},{"id":"q3","question":"¿En qué tipo de auto se construye la máquina del tiempo?","options":[{"id":"a","text":"Un DeLorean","is_correct":true},{"id":"b","text":"Un Corvette","is_correct":false},{"id":"c","text":"Un Mustang","is_correct":false},{"id":"d","text":"Un Ferrari","is_correct":false}],"explanation":"Doc eligió el DeLorean DMC-12, con su carrocería de acero inoxidable y puertas de ala de gaviota."},{"id":"q4","question":"¿A qué año viaja Marty en la primera película?","options":[{"id":"a","text":"1985","is_correct":false},{"id":"b","text":"2015","is_correct":false},{"id":"c","text":"1885","is_correct":false},{"id":"d","text":"1955","is_correct":true}],"explanation":"Marty llega a 1955 y conoce a sus padres adolescentes."},{"id":"q5","question":"¿Cómo se llama el perro de Doc Brown en 1985?","options":[{"id":"a","text":"Einstein","is_correct":true},{"id":"b","text":"Mozart","is_correct":false},{"id":"c","text":"Tesla","is_correct":false},{"id":"d","text":"Galileo","is_correct":false}],"explanation":"Einstein es el primer viajero del tiempo; en 1955 el perro de Doc se llama Copérnico."},{"id":"q6","question":"¿Qué canción de Chuck Berry toca Marty en el baile Encantamiento bajo el Mar?","options":[{"id":"a","text":"«Roll Over Beethoven»","is_correct":false},{"id":"b","text":"«Johnny B. Goode»","is_correct":true},{"id":"c","text":"«Sweet Little Sixteen»","is_correct":false},{"id":"d","text":"«Maybellene»","is_correct":false}],"explanation":"Marty interpreta «Johnny B. Goode» y Marvin Berry llama a su primo Chuck."},{"id":"q7","question":"¿Con qué combustible funciona originalmente la máquina del tiempo del DeLorean?","options":[{"id":"a","text":"Uranio","is_correct":false},{"id":"b","text":"Energía solar","is_correct":false},{"id":"c","text":"Plutonio","is_correct":true},{"id":"d","text":"Mr. Fusión","is_correct":false}],"explanation":"Funciona con el plutonio robado a los terroristas libios; Mr. Fusión solo aparece al final."},{"id":"q8","question":"¿A qué año viajan Doc y Marty en Regreso al Futuro Parte II?","options":[{"id":"a","text":"2025","is_correct":false},{"id":"b","text":"1999","is_correct":false},{"id":"c","text":"1885","is_correct":false},{"id":"d","text":"2015","is_correct":true}],"explanation":"Viajan al 21 de octubre de 2015, un futuro de aerotablas y autos voladores."}]'::jsonb,
